import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next(), t = next();
        int j = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i), next = c == 'z' ? 'a' : (char) (c + 1);
            // Greedy: match as early as possible, keeping c or its cyclic successor.
            if (c == t.charAt(j) || next == t.charAt(j)) j++;
            if (j == t.length()) {
                System.out.println("YES");
                return;
            }
        }
        System.out.println("NO");
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	s, t := readToken(), readToken()
	j := 0
	for i := 0; i < len(s); i++ {
		c, next := s[i], s[i]+1
		if c == 'z' {
			next = 'a'
		}
		// Greedy: match as early as possible, keeping c or its cyclic successor.
		if c == t[j] || next == t[j] {
			j++
		}
		if j == len(t) {
			fmt.Println("YES")
			return
		}
	}
	fmt.Println("NO")
}
